#!/usr/bin/env Rscript
# Success denominators and statistics are generated by the common summarizer.
a <- commandArgs(trailingOnly=FALSE)
p <- sub("^--file=", "", a[grepl("^--file=",a)][1])
script <- file.path(dirname(normalizePath(p)),"summarize_results.py")
status <- system2(Sys.getenv("WIRE_PYTHON","python3"),c(shQuote(script),vapply(commandArgs(trailingOnly=TRUE),shQuote,character(1))))
quit(status=status)
